import{_ as e,o as i,c as s,ae as r}from"./chunks/framework.Czhw_PXq.js";const h=JSON.parse('{"title":"Quality Assurance & Metrics Policy: TenderCheckAI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/quality_metrics.md","filePath":"standards/quality_metrics.md"}'),a={name:"standards/quality_metrics.md"};function o(c,t,n,l,g,u){return i(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="quality-assurance-metrics-policy-tendercheckai" tabindex="-1">Quality Assurance &amp; Metrics Policy: TenderCheckAI <a class="header-anchor" href="#quality-assurance-metrics-policy-tendercheckai" aria-label="Permalink to &quot;Quality Assurance &amp; Metrics Policy: TenderCheckAI&quot;">​</a></h1><h2 id="cite-start-1-strategic-honest-coverage-the-100-80-0-system-cite-1729" tabindex="-1">[cite_start]1. Strategic &quot;Honest Coverage&quot;: The 100/80/0 System [cite: 1729] <a class="header-anchor" href="#cite-start-1-strategic-honest-coverage-the-100-80-0-system-cite-1729" aria-label="Permalink to &quot;[cite_start]1. Strategic &quot;Honest Coverage&quot;: The 100/80/0 System [cite: 1729]&quot;">​</a></h2><p>[cite_start]Instead of chasing a blind percentage, categorize code by business risk to focus testing resources where they matter most. We adopt the <strong>&quot;Honest Coverage&quot;</strong> philosophy: prioritize real logic over boilerplate inflation[cite: 1730].</p><ul><li>[cite_start]<strong>CORE (100% Coverage Mandatory)</strong>: [cite: 1731] <ul><li>[cite_start]<strong>Criteria</strong>: The &quot;Hard Base&quot;. Zero tolerance for logic errors[cite: 1733].</li><li>[cite_start]<strong>Examples</strong>: <code>src/domain</code> logic, business rules, and AI evaluators[cite: 1734].</li><li>[cite_start]<strong>Action</strong>: Vitest must enforce 100% statements/branches/lines[cite: 1735, 1736].</li></ul></li><li>[cite_start]<strong>GLOBAL (Target 80% Coverage)</strong>: [cite: 1736] <ul><li>[cite_start]<strong>Criteria</strong>: Orchestration, UI, and Adapters. Reaching higher percentages here often inflates metrics by testing 3rd party boilerplate[cite: 1739].</li><li>[cite_start]<strong>Examples</strong>: Application services, controllers, and database adapters[cite: 1740, 1741].</li><li>[cite_start]<strong>Action</strong>: Focus on primary user flows. Accept 80% as a threshold for &quot;Honest&quot; verification[cite: 1742].</li></ul></li><li>[cite_start]<strong>INFRASTRUCTURE (0% Coverage)</strong>: [cite: 1743] <ul><li>[cite_start]<strong>Criteria</strong>: Purely static or type-checking code[cite: 1745].</li><li>[cite_start]<strong>Examples</strong>: Constants, mocks, and type files (e.g., <code>types.ts</code>)[cite: 1746].</li></ul></li></ul><h2 id="cite-start-2-actionable-metrics-decision-driving-cite-1747" tabindex="-1">[cite_start]2. Actionable Metrics (Decision-Driving) [cite: 1747] <a class="header-anchor" href="#cite-start-2-actionable-metrics-decision-driving-cite-1747" aria-label="Permalink to &quot;[cite_start]2. Actionable Metrics (Decision-Driving) [cite: 1747]&quot;">​</a></h2><p>[cite_start]Avoid vanity metrics; prioritize data that enables specific technical or business decisions[cite: 1748, 1749].</p><ul><li>[cite_start]<strong>Test Success Rate</strong>: [cite: 1751] <ul><li>[cite_start]<strong>Thresholds</strong>: If it drops below 95%, halt new feature development to fix tests[cite: 1753]. [cite_start]Below 90% triggers a &quot;Code Freeze&quot;[cite: 1754].</li></ul></li><li>[cite_start]<strong>Production Error Rate</strong>: [cite: 1755] <ul><li><strong>Thresholds</strong>: Investigate immediately if &gt;1%. [cite_start]Declare an emergency if &gt;2%[cite: 1756].</li></ul></li><li>[cite_start]<strong>Mean Time to Recovery (MTTR)</strong>: [cite: 1757] <ul><li>[cite_start]<strong>Goal</strong>: Measure team speed in fixing issues to understand maintenance health[cite: 1758].</li></ul></li><li>[cite_start]<strong>Visual Feedback</strong>: Use Binary Thresholds (Red/Green) in the console/dashboard for instant health assessment[cite: 1759].</li></ul><h2 id="cite-start-3-automation-with-quality-gates-husky-cite-1760" tabindex="-1">[cite_start]3. Automation with Quality Gates (Husky) [cite: 1760] <a class="header-anchor" href="#cite-start-3-automation-with-quality-gates-husky-cite-1760" aria-label="Permalink to &quot;[cite_start]3. Automation with Quality Gates (Husky) [cite: 1760]&quot;">​</a></h2><p>[cite_start]Use Git Hooks managed by Husky to prevent defective code from entering the repository[cite: 1761].</p><ul><li>[cite_start]<strong>Pre-Commit (Fast &lt; 2 min)</strong>: [cite: 1762] <ul><li>[cite_start]<strong>Tasks</strong>: Linting and basic unit tests to prevent simple syntax or style errors[cite: 1763, 1764].</li></ul></li><li>[cite_start]<strong>Pre-Push (Exhaustive 2-5 min)</strong>: [cite: 1765] <ul><li>[cite_start]<strong>Tasks</strong>: Strategic coverage checks (100/80/0) and E2E tests[cite: 1766].</li><li>[cite_start]<strong>Goal</strong>: Block any code that fails thresholds before it reaches CI[cite: 1767, 1768].</li></ul></li></ul><h2 id="cite-start-4-observable-testing-debugging-cite-1769" tabindex="-1">[cite_start]4. Observable Testing &amp; Debugging [cite: 1769] <a class="header-anchor" href="#cite-start-4-observable-testing-debugging-cite-1769" aria-label="Permalink to &quot;[cite_start]4. Observable Testing &amp; Debugging [cite: 1769]&quot;">​</a></h2><p>[cite_start]Leverage built-in tools over custom ones to reduce debugging time from hours to minutes[cite: 1770].</p><ul><li>[cite_start]<strong>HTML Reports</strong>: Use native reports to identify performance bottlenecks and slow tests[cite: 1771].</li><li>[cite_start]<strong>Trace Viewer</strong>: Enable &quot;retain-on-failure&quot; traces in Playwright to see network requests, screenshots, and logs step-by-step for every failure[cite: 1772, 1773].</li><li>[cite_start]<strong>JSON Reports</strong>: Utilize native JSON output to automatically extract success rates and durations without complex scripts[cite: 1775].</li></ul>',13)])])}const m=e(a,[["render",o]]);export{h as __pageData,m as default};
